typename context_type::format_arg take_arg(int arg_index = -1) {
  parse_arg_index_ = arg_index;
  if (arg_index < 0) {
    arg_index = context_.parse_context().next_arg_id();
    parse_flags_mask_ &= ~0x80000000u;
  } else {
    context_.parse_context().check_arg_id(--arg_index);
    parse_flags_mask_ |= 0x80000000u;
  }
  parse_arg_index_ = arg_index;
  return detail::get_arg(context_, arg_index);
}

