  if (int_digit_count_ < 0) int_digit_count_ = 0;
}

void limit_int_precision(format_specs& specs) {
  int_digit_count_ = int_digit_count_ < 0 ? 0 : int_digit_count_;
  if (specs.precision < 0) {
    int_base_ = int_base_ == 0 ? 10 : int_base_;
